    const usage=c.show_stats?(c.metrics?v.metrics:[...w.groups('usage').filter(f=>['water_usage','energy'].includes(f.key)),...(v.power?[v.power]:[])]):[];
    const opened=this.shadowRoot.querySelector('details[data-washer-settings]')?.open;
